import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"接入 Kafka 并配置输出","description":"配置 Kafka 安全连接与消费规则，获取样本、映射输出，并核对分区、消息位置和正式消费。","frontmatter":{"title":"接入 Kafka 并配置输出","description":"配置 Kafka 安全连接与消费规则，获取样本、映射输出，并核对分区、消息位置和正式消费。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/kafka-outputs.md","filePath":"zh/使用指南/接入Kafka并配置输出.md"}'),i={name:"zh/guide/kafka-outputs.md"};function s(p,a,n,l,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="接入-kafka-并配置输出" tabindex="-1">接入 Kafka 并配置输出 <a class="header-anchor" href="#接入-kafka-并配置输出" aria-label="Permalink to &quot;接入 Kafka 并配置输出&quot;">​</a></h1><p>入口：<strong>数据中心 → 接入源 → 新建连接 → Kafka</strong>。先准备 Broker 地址列表、安全协议、必要的 SASL/TLS 凭据、Topic 与访问授权。</p><p>平台需要能访问 Broker 实际公布的地址，不仅是第一台引导地址。消费组和起始位置可能影响数据处理安排，应先与消息服务负责人确认。</p><h2 id="_1-保存连接" tabindex="-1">1. 保存连接 <a class="header-anchor" href="#_1-保存连接" aria-label="Permalink to &quot;1. 保存连接&quot;">​</a></h2><p>按服务要求填写地址和认证选项，测试后创建连接。PLAINTEXT、SSL、SASL 等方式必须与服务端匹配，不用关闭加密绕过证书错误。</p><p>连接测试通过只说明本次连接条件，不能证明所有 Topic、分区和输出都可用。</p><h2 id="_2-创建消费规则" tabindex="-1">2. 创建消费规则 <a class="header-anchor" href="#_2-创建消费规则" aria-label="Permalink to &quot;2. 创建消费规则&quot;">​</a></h2><p>打开连接工作台，新建消费规则，填写名称、标识、Topic、消费组、分区及起始位置等实际字段，保存后在左侧树找回。</p><ul><li>最早、最新和指定位置的含义不同，首次使用前确认是否需要历史消息。</li><li>不随意共用另一个生产系统的消费组。</li><li>标识影响输出路径，改名和改标识不是同一个动作。</li></ul><h2 id="_3-拉取样本并配置输出" tabindex="-1">3. 拉取样本并配置输出 <a class="header-anchor" href="#_3-拉取样本并配置输出" aria-label="Permalink to &quot;3. 拉取样本并配置输出&quot;">​</a></h2><p>打开对应规则，使用 <strong>“拉取样本”</strong>，先核对 Topic、分区、位置、载荷和时间。条数过多或服务有压力时缩小检查范围。</p><p>无法访问真实服务时，可使用 **“编辑 / 粘贴样例”**准备结构，但必须知道这是样例，不是实时消费。</p><p>根据 JSON、文本或二进制的实际形式设置输出，检查字段提取和数据类型，点击 <strong>“保存输出”</strong>。输出给计算和报警时，明确选取数值或状态，避免把完整消息对象当作一个温度。</p><h2 id="_4-核对数据点和分区" tabindex="-1">4. 核对数据点和分区 <a class="header-anchor" href="#_4-核对数据点和分区" aria-label="Permalink to &quot;4. 核对数据点和分区&quot;">​</a></h2><p>到“数据点”按实际路径查找，查看来源与当前值；需要修改时返回对应连接和消费规则。</p><p>分区分别有消息顺序和位置，不能把不同分区结果任意拼成一个全局“最新值”。样本来自某次拉取，不等于正式消费者已经处理到相同位置。</p><h2 id="_5-持续运行" tabindex="-1">5. 持续运行 <a class="header-anchor" href="#_5-持续运行" aria-label="Permalink to &quot;5. 持续运行&quot;">​</a></h2><p>正式使用时核对部署中的连接、消费组、分区、恢复位置、输出和运行记录。不要为解决一条解析错误直接清理 Topic、删除组进度或重置消费位置。</p><p>结果异常时先区分连接、授权、无新消息、样本结构、字段映射和部署内容，不一次性重建所有规则。</p><p>下一步：<a href="/induframe-docs/zh/guide/compute-datapoints.html">计算单元</a> · <a href="/induframe-docs/zh/guide/point-alarms.html">报警配置</a> · <a href="/induframe-docs/zh/guide/access-sources.html">接入源总览</a>。</p>',20)])])}const u=e(i,[["render",s]]);export{_ as __pageData,u as default};
